import static thaumcraft.test.ThaumaturgyProbe.*;
import static thaumcraft.test.AdvancedFocusProbe.Q;

@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class AdvancedFocusClient {
    static int ticks,stage;static ServerPlayer owner;static FocalEntity table;static Zombie target;static List<FocusFieldEntity> clouds=List.of();static FocusFieldEntity mine;static long started;static float health;
    static List<FocusFieldEntity> fields(ServerLevel l){return l.getEntitiesOfClass(FocusFieldEntity.class,new AABB(Q).inflate(24));}
    static Zombie mob(ServerPlayer p,Vec3 at){var z=new Zombie(p.level());z.setNoAi(true);z.setNoGravity(true);z.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));z.setPos(at);p.level().addFreshEntity(z);return z;}
    static void equip(ServerPlayer p,FocusProgram program){var stack=p.getMainHandItem();if(!(stack.getItem() instanceof CasterItem)){stack=item("caster_basic");p.setItemInHand(InteractionHand.MAIN_HAND,stack);}var focus=item("focus_3");focus.set(ThaumaturgyContent.PROGRAM.get(),program);p.setItemInHand(InteractionHand.OFF_HAND,focus);check(((CasterItem)stack.getItem()).swap(p,stack),"Physical graph focus swap failed");p.setYRot(0);p.setXRot(0);}
    static void cast(ServerPlayer p,FocusProgram program){equip(p,program);float before=thaumcraft.aura.AuraManager.get(p.level(),p.blockPosition()).vis();check(p.getMainHandItem().getItem().use(p.level(),p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS,"Advanced glove cast failed");float after=thaumcraft.aura.AuraManager.get(p.level(),p.blockPosition()).vis();check(Math.abs(before-after-thaumcraft.equipment.EquipmentContent.visCost(p,program.vis()))<.002,"Graph did not pay aura once");}
    static FocusProgram spell(String medium,String effect){return new FocusProgram(medium,List.of(new FocusProgram.Effect(effect,1,1)));}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("advanced-client")||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
        if(stage==0){owner=p;l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.SPAWN_MOBS,false,e.server());l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.SPAWN_PHANTOMS,false,e.server());p.setHealth(p.getMaxHealth());p.setGameMode(GameType.SURVIVAL);for(var field:fields(l))field.discard();for(var entity:l.getEntitiesOfClass(LivingEntity.class,new AABB(Q).inflate(64)))if(entity!=p)entity.discard();for(var q:BlockPos.betweenClosed(Q.offset(-8,-1,-8),Q.offset(8,4,12)))l.setBlockAndUpdate(q,q.getY()==204?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(Q,ThaumaturgyContent.TABLE.get().defaultBlockState());table=(FocalEntity)l.getBlockEntity(Q);p.teleportTo(l,40.5,206,8.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET))p.setItemSlot(slot,ItemStack.EMPTY);knowledge(p);
            table.inventory.setItem(0,item("focus_3"));var menu=new FocalMenu(60,p.getInventory(),table);check(menu.clickMenuButton(p,7)&&table.draft.modifier().equals("scatter"),"Cannot select scatter");check(menu.clickMenuButton(p,9)&&table.draft.forks()==3&&menu.clickMenuButton(p,10)&&table.draft.cone()==30,"Scatter controls failed");check(menu.clickMenuButton(p,7)&&table.draft.split()&&menu.clickMenuButton(p,8)&&menu.clickMenuButton(p,2),"Cannot edit second path");check(table.draft.effects().getFirst().kind().equals("fire")&&table.draft.branches().getFirst().effects().getFirst().kind().equals("air"),"Branch edit changed wrong path");var other=new FocalMenu(61,p.getInventory(),table);check(other.clickMenuButton(p,3)&&table.draft.effects().getFirst().power()==2&&table.draft.branches().getFirst().effects().getFirst().power()==1,"Menu editors share branch selection");
            AdvancedFocusProbe.editorAndCosts(p,table);var scatter=new FocusProgram("projectile",List.of(new FocusProgram.Effect("earth",1,1)),"scatter",4,10,1,5,false,List.of());cast(p,scatter);var shots=l.getEntitiesOfClass(FocusProjectile.class,p.getBoundingBox().inflate(2));check(shots.size()==4,"Scatter did not spawn four native projectiles");for(var shot:shots)shot.discard();stage=1;ticks=0;return;}
        if(stage==1){var split=spell("projectile","earth").modifier("split_trajectory").replace(1,new FocusProgram.Branch("projectile",List.of(new FocusProgram.Effect("frost",1,1))));target=mob(p,p.position().add(0,0,5));cast(p,split);check(l.getEntitiesOfClass(FocusProjectile.class,p.getBoundingBox().inflate(2)).size()==2,"Split trajectory did not spawn both paths");stage=2;ticks=60;return;}
        if(stage==2){check(target.getHealth()<20&&target.hasEffect(MobEffects.SLOWNESS),"Separate projectile paths lost damage or frost");target.discard();stage=3;ticks=0;return;}
        if(stage==3){var split=spell("bolt","fire").modifier("split_target").replace(1,new FocusProgram.Branch("touch",List.of(new FocusProgram.Effect("curse",1,1))));target=mob(p,p.position().add(0,0,4));equip(p,split);var state=ResearchService.state(p);check(KnowledgeStore.write(p,state.stage("FOCUSSPLIT",0)),"Cannot prepare research denial");float before=thaumcraft.aura.AuraManager.get(l,p.blockPosition()).vis();check(p.getMainHandItem().getItem().use(l,p,InteractionHand.MAIN_HAND)==InteractionResult.FAIL&&thaumcraft.aura.AuraManager.get(l,p.blockPosition()).vis()==before,"Missing split research debited aura or cast");KnowledgeStore.write(p,state);cast(p,split);check(target.getHealth()<20&&target.hasEffect(MobEffects.WEAKNESS),"Split target did not execute both effect paths: health="+target.getHealth()+", weakness="+target.hasEffect(MobEffects.WEAKNESS)+", target="+target.position()+", owner="+p.position()+", aim="+SpellEngine.aim(p,32)+", program="+split);target.discard();stage=4;ticks=0;return;}
        if(stage==4){target=mob(p,p.position().add(0,0,4));var cloud=new FocusProgram("cloud",List.of(new FocusProgram.Effect("earth",2,1)),"none",2,10,2,5,false,List.of());cast(p,cloud);SpellEngine.cast(p,cloud);clouds=fields(l).stream().filter(f->!f.mine()).toList();check(clouds.size()==2,"Cannot create overlapping clouds");started=now;stage=5;ticks=50;return;}
        if(stage==5){check(Math.abs(target.getHealth()-17)<.01,"Overlapping clouds bypassed shared immunity: "+target.getHealth());check(clouds.stream().noneMatch(Entity::isRemoved),"Cloud expired before configured deadline");stage=6;ticks=60;return;}
        if(stage==6){check(target.getHealth()<=14&&target.getHealth()>=13.9,"Cloud did not hit again after shared cooldown: "+target.getHealth());for(var f:clouds)f.discard();target.discard();p.teleportTo(l,44.5,205,12.5,Set.of(),0,55,true);p.setDeltaMovement(Vec3.ZERO);var program=spell("mine","earth");equip(p,program);p.setXRot(55);SpellEngine.cast(p,program);mine=fields(l).stream().filter(FocusFieldEntity::mine).findFirst().orElseThrow();target=mob(p,mine.position().add(0,-.05,0));started=now;stage=7;ticks=60;return;}
        if(stage==7){check(!mine.armed()&&!mine.isRemoved()&&target.getHealth()==20,"Mine triggered before forty-tick arming period");stage=8;ticks=50;return;}
        if(stage==8){check(mine.isRemoved()&&target.getHealth()<20,"Enemy mine failed to trigger exactly once");target.discard();p.setHealth(10);var support=Q.offset(6,-1,6);l.setBlockAndUpdate(support,Blocks.STONE.defaultBlockState());p.teleportTo(l,support.getX()+.5,205,support.getZ()+.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);mine=new FocusFieldEntity(ThaumaturgyContent.FIELD.get(),l);mine.configure(p,new FocusProgram("mine",List.of(new FocusProgram.Effect("heal",2,1)),"none",2,10,1,5,true,List.of()),p.position().add(0,.05,0),1,support);l.addFreshEntity(mine);target=mob(p,p.position().add(.4,0,0));stage=9;ticks=35;return;}
        if(stage==9){check(mine.isRemoved()&&p.getHealth()>=14&&target.getHealth()==20,"Friendly mine failed owner selection/healing");target.discard();var support=Q.offset(-4,-1,4);l.setBlockAndUpdate(support,Blocks.STONE.defaultBlockState());mine=new FocusFieldEntity(ThaumaturgyContent.FIELD.get(),l);mine.configure(p,spell("mine","earth"),Vec3.atCenterOf(support).add(0,.55,0),1,support);l.addFreshEntity(mine);l.setBlockAndUpdate(support,Blocks.DIRT.defaultBlockState());stage=10;ticks=79;return;}
        if(stage==10){check(mine.isRemoved(),"Unsupported mine survived support replacement");check(!table.working()&&table.inventory.getItem(0).get(ThaumaturgyContent.PROGRAM.get()).equals(AdvancedFocusProbe.graph()),"Advanced native work did not finish");p.teleportTo(l,40.5,206,8.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);table.draft=AdvancedFocusProbe.graph();p.setGameMode(GameType.CREATIVE);p.openMenu(table);stage=11;Thaumcraft.LOGGER.info("FOCUS_ADVANCED_CLIENT_EFFECTS_OK: isolated branch editor, one aura payment, scatter x4, split projectile collisions, split impact/research, shared cloud immunity, enemy/friendly arming and support invalidation");}
    }
}
